effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

          #define t progressa

        //random hash
        vec4 hash42(vec2 p){

        	vec4 p4 = fract(vec4(p.xyxy) * vec4(443.8975,397.2973, 491.1871, 470.7827));
            p4 += dot(p4.wzxy, p4+19.19);
            return fract(vec4(p4.x * p4.y, p4.x*p4.z, p4.y*p4.w, p4.x*p4.w));
        }


        float hash( float n ){
            return fract(sin(n)*43758.5453123);
        }


        float n( in vec3 x ){
            vec3 p = floor(x);
            vec3 f = fract(x);
            f = f*f*(3.0-2.0*f);
            float n = p.x + p.y*57.0 + 113.0*p.z;
            float res = mix(mix(mix( hash(n+  0.0), hash(n+  1.0),f.x),
                                mix( hash(n+ 57.0), hash(n+ 58.0),f.x),f.y),
                            mix(mix( hash(n+113.0), hash(n+114.0),f.x),
                                mix( hash(n+170.0), hash(n+171.0),f.x),f.y),f.z);
            return res;
        }

        //tape noise
        float nn(vec2 p){


            float y = p.y;
            float s = t*2.;

            float v = (n( vec3(y*.01 +s, 			1., 1.0) ) + .0)
                  	 *(n( vec3(y*.011+1000.0+s, 	1., 1.0) ) + .0) 
                  	 *(n( vec3(y*.51+421.0+s, 	1., 1.0) ) + .0)   
                ;
            //v*= n( vec3( (fragCoord.xy + vec2(s,0.))*100.,1.0) );
           	v*= hash42(   vec2(p.x +t*0.01, p.y) ).x +.3 ;


            v = pow(v+.3, 1.);
        	if(v<.7) v = 0.;  //threshold
            return v;
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        /////////////////////////

    	vec4 fragColor;

            vec2 uv = TanRyu;

            float linesN = progressc; //fields per seconds
            float one_y = acScreenSize.y / linesN; //field line
            uv = floor(uv*(vec2(acScreenSize.x, acScreenSize.y))/one_y)*one_y;

            float col =  nn(uv);

            vec4 bcol = mix(color1, color2, col);

            fragColor = bcol;

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (newLayer(texColor, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
